.jcs{display:block;position:relative;background:var(--jc-bg);color:var(--jc-ink);isolation:isolate}.jcs__stage{position:relative;max-width:1680px;margin:auto;overflow:hidden;background:var(--jc-bg)}.jcs__scene{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:24px;padding:48px 24px;text-align:center;min-height:600px}.jcs__product{height:330px;width:min(480px,80vw);flex:none}.jcs__product img{width:100%;height:100%;object-fit:contain;display:block;filter:drop-shadow(0 12px 12px #241c1814)}.jcs__copy{max-width:780px}.jcs .jcs__heading{font-family:var(--jc-heading-font);font-weight:var(--jc-heading-weight);font-size:var(--jc-heading-size);letter-spacing:var(--jc-heading-tracking);line-height:var(--jc-heading-leading);margin:0 0 16px}.jcs__heading span{display:block}.jcs .jcs__body{font-family:var(--jc-body-font);font-weight:var(--jc-body-weight);font-size:var(--jc-body-size);letter-spacing:var(--jc-body-tracking);line-height:var(--jc-body-leading);max-width:540px;margin:auto}.jcs__body p{margin:0}.jcs__body strong{font-weight:700}.jcs__skip{position:absolute;left:-10000px;top:14px;z-index:10;padding:12px 18px;border-radius:30px;background:var(--jc-bg);color:var(--jc-ink);font:var(--jc-button-weight) var(--jc-button-size)/var(--jc-button-leading) var(--jc-button-font);letter-spacing:var(--jc-button-tracking)}.jcs__skip:focus{position:fixed;left:20px;top:100px;outline:2px solid var(--jc-ink)}.jcs__flowers,.jcs__duster,.jcs__footprints{display:none;position:absolute;inset:0;pointer-events:none}.jcs[data-pinned=true]{height:var(--jcs-runway)}.jcs[data-pinned=true] .jcs__stage{position:sticky;top:var(--jcs-top);height:var(--jcs-height)}.jcs[data-pinned=true] .jcs__scene{position:absolute;inset:0;min-height:0;padding:20px;gap:20px;opacity:0;visibility:hidden;will-change:transform,opacity;pointer-events:none}.jcs[data-pinned=true] .jcs__product{height:calc(var(--jcs-height)*var(--jcs-product)/100)}.jcs[data-pinned=true] .jcs__flowers,.jcs[data-pinned=true] .jcs__footprints{display:block;z-index:2}.jcs__flowers svg{position:absolute;left:50%;top:45%;width:70px;height:70px;opacity:0;color:var(--jc-accent);will-change:transform,opacity}.jcs__flowers svg:nth-child(3n){color:var(--jcs-secondary)}.jcs__flowers svg:nth-child(3n + 1){color:var(--jc-ink)}.jcs[data-pinned=true] .jcs__duster{display:block;inset:auto;left:0;top:0;width:150px;height:100px;z-index:4;opacity:0;will-change:transform}.jcs__duster svg{width:100%;height:100%;filter:drop-shadow(0 10px 7px #241c1820)}.jcs__footprints svg{position:absolute;width:42px;height:76px;fill:var(--jc-ink);opacity:0;will-change:opacity,transform}.jcs:not([data-pinned=true]) .jcs__scene{opacity:1!important;visibility:visible!important;transform:none!important;clip-path:none!important}.jcs:not([data-pinned=true]) .jcs__scene+.jcs__scene{border-top:1px solid color-mix(in srgb,var(--june-ink,#171717) 8.24%,transparent)}
@media(max-width:900px){.jcs .jcs__heading{font-size:var(--jc-heading-mobile)}.jcs .jcs__body{font-size:var(--jc-body-mobile)}.jcs__scene{min-height:520px;padding:34px 20px}.jcs__product{height:260px}.jcs[data-pinned=true] .jcs__product{height:calc(var(--jcs-height)*var(--jcs-mobile)/100);width:80vw}.jcs[data-pinned=true] .jcs__scene{gap:18px}.jcs__copy{max-width:100%}.jcs .jcs__heading{margin-bottom:12px}.jcs__flowers svg{width:48px;height:48px}.jcs__footprints svg{width:30px;height:54px}.jcs[data-pinned=true] .jcs__duster{width:110px;height:75px}.jcs__skip{font-size:var(--jc-button-mobile)}}
