{% schema %}
{
  "name": "June · Other chapters",
  "tag": "section",
  "class": "june-chapters-section",
  "settings": [
    {
      "type": "checkbox",
      "id": "use_master_palette",
      "label": "Use master palette",
      "default": true,
      "info": "Uses Theme settings > June master palette. Turn off to use this section’s individual colours."
    },
    {
      "type": "text",
      "id": "eyebrow",
      "label": "Eyebrow",
      "default": "Other chapters"
    },
    {
      "type": "text",
      "id": "skip",
      "label": "Skip link",
      "default": "Skip the story"
    },
    {
      "type": "checkbox",
      "id": "scroll",
      "label": "Enable pinned scroll story",
      "default": true
    },
    {
      "type": "checkbox",
      "id": "motion",
      "label": "Enable decorative motion",
      "default": true
    },
    {
      "type": "range",
      "id": "offset",
      "label": "Sticky header clearance",
      "min": 0,
      "max": 150,
      "step": 5,
      "unit": "px",
      "default": 85
    },
    {
      "type": "font_picker",
      "id": "fallback_font",
      "label": "Fallback font",
      "default": "poppins_n4"
    },
    {
      "type": "color",
      "id": "background",
      "label": "Story background",
      "default": "#FFFFFF"
    },
    {
      "type": "color",
      "id": "ink",
      "label": "Text",
      "default": "#171717"
    },
    {
      "type": "color",
      "id": "accent",
      "label": "Flowers and duster",
      "default": "#F56A28"
    },
    {
      "type": "color",
      "id": "flower_secondary",
      "label": "Secondary flower colour",
      "default": "#DADADA"
    },
    {
      "type": "range",
      "id": "pace",
      "label": "Scroll distance per story beat",
      "min": 30,
      "max": 100,
      "step": 5,
      "unit": "vh",
      "default": 55
    },
    {
      "type": "range",
      "id": "blank_hold",
      "label": "Blank pause after wedding",
      "min": 5,
      "max": 30,
      "step": 1,
      "default": 13,
      "info": "Tenths of a story beat. Duration depends on scrolling speed."
    },
