.jl .jl__gift-summary{position:static;margin:8px 0!important;max-width:100%;padding:0;border:0;background:transparent}.jl__gift-summary summary{min-height:44px;text-decoration:underline;text-underline-offset:4px}.jl__gift-summary ul{max-width:360px}.jl__shopping{align-items:start}.jl__scene{overflow:visible}@media(max-width:900px){.jl__planner{height:200px!important}.jl__scene:before{height:200px}.jl__header{gap:12px!important;padding-top:24px!important}.jl__shopping{padding-inline:20px!important}.jl__cover-name{font-size:var(--jl-label-mobile)!important}}

@media(max-width:900px){.jl__gift-summary{display:none}.jl__scene .jl__reveal{position:relative;z-index:10;margin:12px auto;display:flex;width:calc(100% - 40px);max-width:350px;justify-content:space-between}.jl .jl__scene{height:auto!important;min-height:0!important}.jl .jl__cover{width:auto;flex:1;min-width:0}.jl .jl__cover-name{font-size:var(--jl-button-mobile)!important;line-height:1.35}.jl .jl__covers{gap:8px}.jl__shopping{gap:12px!important}.jl__planner{height:170px!important}.jl__swipe{margin-bottom:12px!important}}

